# clean reimplementation: no-extras maximal rects, min-count exact cover
def valid_raw(G,r0,r1,c0,c1):
    ones=[(r,c) for r in range(r0,r1+1) for c in range(c0,c1+1) if G[r,c]==1]
    if not ones or r1<=r0 or c1<=c0: return False
    if not any(r==r0 for r,c in ones): return False
    if not any(r==r1 for r,c in ones): return False
    if not any(c==c0 for r,c in ones): return False
    if not any(c==c1 for r,c in ones): return False
    return all(not (r0<r<r1 and c0<c<c1) for r,c in ones)

