from collections import deque
def comps_of(G):
    H=len(G); W=len(G[0]); seen=[[False]*W for _ in G]; out=[]
    for r in range(H):
        for c in range(W):
            if G[r][c]==1 and not seen[r][c]:
                st=[(r,c)]; seen[r][c]=True; cells=[]
                while st:
                    a,b=st.pop(); cells.append((a,b))
                    for da in (-1,0,1):
                        for db in (-1,0,1):
                            if da==0 and db==0: continue
                            na,nb=a+da,b+db
                            if 0<=na<H and 0<=nb<W and G[na][nb]==1 and not seen[na][nb]:
                                seen[na][nb]=True; st.append((na,nb))
                out.append(cells)
    return out

def has_cycle(cells):
    S=set(cells)
    adj={p:[] for p in cells}
    for (r,c) in cells:
        for dr,dc in ((1,0),(0,1),(-1,0),(0,-1)):
            n=(r+dr,c+dc)
            if n in S: adj[(r,c)].append(n)
    vis=set()
    def dfs(p,parent):
        vis.add(p)
        for n in adj[p]:
            if n!=parent:
                if n in vis: return True
                if dfs(n,p): return True
        return False
    for p in cells:
        if p not in vis and dfs(p,None): return True
    return False

